<div class="sale-grid"><section class="panel form-panel"><h2>Sale details</h2><form method="post" action="<?= site_url('sales') ?>"><?= csrf_field() ?><label>Product<select name="product_id" id="product" required><option value="">Select a product</option><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>" data-price="<?= esc($p['price']) ?>" <?= (string)old('product_id')===(string)$p['id']?'selected':'' ?>><?= esc($p['name']) ?> · ₱<?= number_format((float)$p['price'],2) ?> · <?= esc($p['stock_quantity']) ?> in stock</option><?php endforeach ?></select></label><label>Customer<select name="customer_id"><option value="">Walk-in customer</option><?php foreach($customers as $c): ?><option value="<?= $c['id'] ?>" <?= (string)old('customer_id')===(string)$c['id']?'selected':'' ?>><?= esc($c['full_name']) ?></option><?php endforeach ?></select></label><label>Quantity<input id="quantity" type="number" name="quantity" min="1" max="2147483647" step="1" value="<?= esc(old('quantity',1)) ?>" required></label><button>Confirm and record sale →</button></form></section><section class="panel sale-summary"><p class="eyebrow">ESTIMATED TOTAL</p><strong id="total">₱0.00</strong><p>Stock and price are checked again when you confirm. A successful sale updates inventory immediately.</p><span class="badge">Recorded under your staff account</span></section></div><script>const p=document.getElementById('product'),q=document.getElementById('quantity');function update(){const n=Number(p.selectedOptions[0]?.dataset.price||0)*Number(q.value||0);document.getElementById('total').textContent=new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(n)}p.addEventListener('change',update);q.addEventListener('input',update);update();</script>
